'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const sets=[[3,6,7],[6,3,7],[5,3,7],[3,5,7],[6,5,7],[5,6,7]];
const names=[['Dark · no light','暗 · 沒有光'],['Red','紅'],['Green','綠'],['Yellow','黃'],['Blue','藍'],['Magenta','洋紅'],['Cyan','青'],['White','白']];
const colors=['#000','#f00','#0f0','#ff0','#00f','#f0f','#0ff','#fff'];
const lamps=['red','green','blue'],bits=[1,2,4];
let variant=OrionProgress.variant('light'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,mask=0,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false;
function target(v=variant,s=stage){return sets[v][s];}
function lampNames(m){return bits.filter(b=>m&b).map(b=>t(...names[b])).join(t(' + ',' ＋ '))||t('All off','全部關閉');}
function resetTrial(){mask=0;solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('light')){variant=v;stage=0;resetTrial();}
function toggle(b){if(solved||!bits.includes(b))return;mask^=b;state='changed';if(!history.includes(mask))history.unshift(mask);render();}
function check(){if(solved)return;if(mask!==target()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('radiance');render();if(stage<2)$('next').focus();}
function hints(){return[t('Switch on one light, then add another. Watch the named colour on your screen.','先開一盞光燈，再加另一盞。觀察屏幕顏色和名稱。'),target()===7?t('Try combining all three lights. Light adds together; it does not behave like paint.','試試把三種光一起開啟。光會相加，跟顏料不同。'):t('This seal needs two lights together. Try different pairs, with the third switched off.','這道封印需要兩種光。試試不同配搭，把第三盞關掉。'),t(`For this seal, leave only ${lampNames(target())} on, then light the seal.`,`這道封印只需開啟${lampNames(target())}光，再點亮封印。`)];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Prism Lantern Vault · Orion','稜光燈密庫 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=complete?t('The optical treasury awakens.','光學寶庫甦醒了。'):t(`Seals illuminated · ${count} / 3`,`已點亮 ${count} / 3 道封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('progressCount').textContent=$('sceneStatus').textContent;$('progressBar').value=count;$('scene').classList.toggle('complete',complete);$('mission').textContent=t('Switch the coloured lanterns on or off. Make your screen match the seal, then light it.','開關彩色光燈，讓你的屏幕跟封印顏色相同，再點亮封印。');lamps.forEach((id,i)=>{const on=Boolean(mask&bits[i]);$(id).setAttribute('aria-pressed',String(on));$(id).disabled=solved;$(id+'Label').textContent=t(...names[bits[i]])+t(' light','光');$(id+'State').textContent=on?t('ON · tap to turn off','開 · 點按關閉'):t('OFF · tap to turn on','關 · 點按開啟');$(id).setAttribute('aria-label',t(`${names[bits[i]][0]} light, ${on?'on':'off'}. Toggle.`,`${names[bits[i]][1]}光，${on?'開':'關'}。點按切換。`));});
 const swatch=(m,label)=>`${label}<span class="spot" style="background:${colors[m]}" aria-hidden="true"></span><strong>${t(...names[m])}</strong>`;$('goal').innerHTML=swatch(target(),t('Seal wants','封印需要'));$('reading').innerHTML=swatch(mask,t('Your screen','你的屏幕'));
 const msg={ready:t('The lamps begin off. What happens when you add their light?','光燈開始時全關。把它們的光加起來會怎樣？'),changed:t('Your screen now shows ','你的屏幕現在是')+t(...names[mask])+t('. Compare it with the seal.','。跟封印比較吧。'),wrong:t('The colours do not match yet. Change the lights and try again.','顏色還未相同。調整光燈，再試一次。'),success:t('Colour matched! A light seal opens.','顏色相同！一道光色封印打開了。')};$('feedback').textContent=msg[state];$('log').innerHTML=history.slice(0,5).map(m=>`<li>${lampNames(m)} → ${t(...names[m])}</li>`).join('')||`<li>${t('Your experiments will appear here.','你的實驗會記錄在這裡。')}</li>`;for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('radiance')?t('Radiance Sigil saved in your collection.','光華符印已存入收藏。'):'';
}
lamps.forEach((id,i)=>$(id).onclick=()=>toggle(bits[i]));$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('red').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('light',variant);observedVariant=OrionProgress.variant('light');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('radiance');render();};
function syncProgress(){const v=OrionProgress.variant('light'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('radiance')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
